 "content": "def transform(grid):
    # Recolor large 4-connected zero regions, using the size of the marked motif as threshold.
    motif = {(3, 9), (4, 8), (5, 7), (6, 6), (7, 5), (7, 7)}
    threshold = len(motif)
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                x, y = stack.pop()
                component.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            if len(component) >= threshold:
                for x, y in component:
                    out[x][y] = 2
    return out
